 if(tests.length)commands.push({kind:'focused',args:['--import','./tests/normal-hosted/no-external.mjs','--test',plan.groups.length===1&&plan.groups[0]==='ui'?'--test-concurrency=2':'--test-concurrency=1',...tests],timeoutMs:plan.groups.includes('integrated')?180000:Math.max(180000,feedbackBudgetMs(plan))});
