const digest=bytes=>createHash('sha256').update(bytes).digest('hex');
const CRITERIA_FILES=['MISSION.md','PRINCIPLES.md','DESIGN.md','CONTRACTS.md'];
const SHIPPING_ROOTS=['src','runtime','dist','docs'],SHIPPING_FILES=['package.json','package-lock.json',...CRITERIA_FILES,'README.md','THIRD_PARTY_NOTICES.md'];
